  {name:'PT Galpon',    key:'pt_galpon',   url:'rtsp://admin:PJWIIK@192.168.1.78:554',   file:'/mnt/usbdata/cams/pt_galpon.jpg'},
  {name:'Molino Chino', key:'molino_chino',url:'rtsp://admin:ABTBSV@192.168.1.173:554',  file:'/mnt/usbdata/cams/molino_chino.jpg'},
