  {name:'CamCom2',      key:'camcom2',     url:'rtsp://admin:PYKXQN@192.168.1.120:554',  file:'/mnt/usbdata/cams/camcom2.jpg'},
  {name:'Playon1',      key:'playon1',     url:'rtsp://admin:Palala81@192.168.1.102:554',file:'/mnt/usbdata/cams/playon1.jpg'},
  {name:'CAM96',        key:'cam96',       url:'rtsp://admin:OQTPQX@192.168.1.96:554',   file:'/mnt/usbdata/cams/cam96.jpg'}
];

flow.set('cameras', cameras);
flow.set('batchIndex', 0);

const status = {};
cameras.forEach(cam => {
  status[cam.key] = {
    name: cam.name,
    key: cam.key,
    file: cam.file,
    lastUpdate: null,
    lastSize: null,
    status: 'unknown',
    error: null
  };
});
flow.set('camStatus', status);
node.log('Camaras inicializadas: ' + cameras.length);
return null;

const cameras = flow.get('cameras');
if (!cameras || cameras.length === 0) return null;

let batchIndex = flow.get('batchIndex') || 0;
const batchSize = 3;
const start = batchIndex * batchSize;
const batch = cameras.slice(start, start + batchSize);

const next = (start + batchSize >= cameras.length) ? 0 : batchIndex + 1;
flow.set('batchIndex', next);

const msgs = batch.map(cam => ({
  payload: `-lc "timeout 15s ffmpeg -hide_banner -loglevel error -rtsp_transport tcp -i '${cam.url}' -vf scale=480:270 -vframes 1 -q:v 31 '${cam.file}' 2>&1"`,
  camKey: cam.key,
  camName: cam.name,
  camFile: cam.file
}));

return [msgs];

if (msg.payload && msg.payload.toString().trim()) {
  const key = msg.camKey || '?';
  node.warn('[' + key + '] stderr: ' + msg.payload.toString().substring(0, 200));
}
return null;

const key = msg.camKey;
const file = msg.camFile;
if (!key) return null;

const status = flow.get('camStatus') || {};
if (!status[key]) return null;

const rc = msg.payload;
const code = (rc !== null && typeof rc === 'object') ? rc.code : parseInt(rc, 10);

if (code === 0) {
  const fs = require('fs');
  try {
    const stat = fs.statSync(file);
    status[key].lastSize = stat.size;
  } catch(e) {
    status[key].lastSize = 0;
  }
  status[key].lastUpdate = Date.now();
  status[key].status = 'ok';
  status[key].error = null;
} else {
  status[key].status = 'error';
  status[key].error = 'cod:' + code;
}

flow.set('camStatus', status);
return null;

const rawKey = msg.req.params.key || '';
const key = rawKey.replace(/[^a-zA-Z0-9_]/g, '');
const file = '/mnt/usbdata/cams/' + key + '.jpg';
const fs = require('fs');

try {
  const data = fs.readFileSync(file);
  msg.payload = data;
  msg.headers = {'Content-Type': 'image/jpeg', 'Cache-Control': 'no-store, no-cache, max-age=0'};
  msg.statusCode = 200;
} catch(e) {
  msg.payload = Buffer.alloc(0);
  msg.headers = {'Content-Type': 'image/jpeg', 'Cache-Control': 'no-store'};
  msg.statusCode = 404;
}
return msg;

const status = flow.get('camStatus');
if (!status) { msg.payload = []; return msg; }

const cameras = flow.get('cameras') || [];
const now = Date.now();
const OLD_SEC = 90;

const ordered = cameras.map(cam => {
  const s = status[cam.key] || {};
  const age = s.lastUpdate ? Math.floor((now - s.lastUpdate) / 1000) : null;
  let uiStatus = s.status || 'unknown';

  if (uiStatus === 'ok' && age !== null && age > OLD_SEC) {
    uiStatus = 'old';
  }

  let statusText = '';
  if (age !== null) {
    if (uiStatus === 'error') {
      statusText = `Error (hace ${age}s)`;
    } else if (uiStatus === 'old') {
      statusText = `Vieja (hace ${age}s)`;
    } else {
      statusText = `Hace ${age}s`;
    }
  } else {
    statusText = (uiStatus === 'error') ? ('Error: ' + (s.error || '')) : 'Sin datos';
  }

  const sizeKB = s.lastSize ? Math.round(s.lastSize / 1024) + ' KB' : '--';

  return {
    key: cam.key,
    name: cam.name,
    status: uiStatus,
    statusText: statusText,
    sizeText: sizeKB,
    ts: s.lastUpdate || 0
  };
});

msg.payload = ordered;
return msg;
